// Test helpers for Cerebral Angular integration
import { ChangeDetectorRef } from '@angular/core'
import { Tag, View } from 'cerebral'
import { CerebralComponent } from '../src/CerebralComponent'

interface StateChange {
  path: string
  value: any
}

export function createMockCdr(): ChangeDetectorRef {
  return {
    detectChanges: jest.fn(),
    markForCheck: jest.fn(),
    detach: jest.fn(),
    reattach: jest.fn(),
    checkNoChanges: jest.fn(),
  }
}

export function setupTestComponent(
  component: CerebralComponent,
  dependencies: { [key: string]: Tag<any> }
): void {
  if (!component.onUpdate) {
    component.onUpdate = function (
      changes: StateChange[] | null,
      force: boolean
    ): void {
      if (!this.view) return

      this.view.updateFromState(changes || [], {}, force)
      this.view.render(
        {},
        (props: Record<string, any>) => {
          Object.keys(props).forEach((key) => {
            ;(this as any)[key] = props[key]
          })
        },
        false
      )

      this._cdr.detectChanges()
    }
  }

  component.view = new View({
    dependencies,
    props: {},
    controller: component._app,
    displayName: 'TestComponent',
    onUpdate: (changes: StateChange[] | null, force: boolean) => {
      component.onUpdate(changes, force)
    },
  })

  component.view.mount()
  component.view.render(
    {},
    (props: Record<string, any>) => {
      Object.keys(props).forEach((key) => {
        ;(component as any)[key] = props[key]
      })
    },
    true
  )
}
